// Helper to get character by X account
export const getCharacterByXAccount = (xAccount: string) => {
  return characters.find((character) =>
    character.profile.some(
      (profileItem) => profileItem.startsWith('Xアカウント:') && profileItem.includes(xAccount)
    )
  );
};

